/*
 * prog56_kruskal_mst.c
 *
 * Re‑implementation of the original program (prog56_kruskal_mst) whose
 * behaviour was observed in the supplied binary.  The program implements
 * Kruskal's Minimum Spanning Tree algorithm.
 *
 * Usage
 * -----
 *   prog56_kruskal_mst N
 *
 *   N – number of vertices (1 … 9).  The program reads edges from
 *   standard input, one per line, in either of the two forms:
 *
 *       u v w          (space separated)
 *       u-v w          (dash between the vertices, space before weight)
 *
 *   where u and v are vertex numbers (0‑based) and w is the edge
 *   weight (integer).  Input is terminated by EOF.
 *
 * Output
 * ------
 *   * If the command line is wrong or N is not a positive integer ≤ 9,
 *     the program prints
 *
 *         INVALID_ARGS
 *
 *   * If the graph is disconnected (i.e. a spanning tree cannot be
 *     built) it prints
 *
 *         DISCONNECTED
 *
 *   * Otherwise it prints the total weight of the MST and the list of
 *     edges that belong to the MST, exactly as the original binary does:
 *
 *         weight=%d edges=%d-%d%d-%d...<newline>
 *
 *   The edge list is printed with the format string "%d-%d" for each
 *   edge, without any separator between successive edges, and a final
 *   newline character.
 *
 * The implementation follows the logic that could be inferred from the
 * decompiled state‑machine: parsing the argument, reading edges,
 * sorting them by weight, a union‑find structure for cycle detection,
 * accumulation of the total weight, and the required output strings.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VERTICES 9          /* limit observed in the original binary */
#define MAX_EDGES    1024       /* generous upper bound for input size */

/* Edge structure */
typedef struct {
    int u, v;
    int w;
} Edge;

/* Disjoint‑set (union‑find) data structure */
static int parent[MAX_VERTICES];

/* Find with path compression */
static int find_set(int x)
{
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return x;
}

/* Simple union (no rank needed for such a tiny graph) */
static void union_set(int a, int b)
{
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra != rb)
        parent[ra] = rb;
}

/* Comparison function for qsort (ascending weight) */
static int cmp_edge(const void *a, const void *b)
{
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    if (ea->w != eb->w)
        return ea->w - eb->w;
    /* deterministic tie‑breaker (not required for correctness) */
    if (ea->u != eb->u)
        return ea->u - eb->u;
    return ea->v - eb->v;
}

int main(int argc, char **argv)
{
    /* ---------- argument handling ---------- */
    if (argc != 2) {
        puts("INVALID_ARGS");
        return 0;
    }

    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n <= 0 || n > MAX_VERTICES) {
        puts("INVALID_ARGS");
        return 0;
    }

    /* ---------- read edges from stdin ---------- */
    Edge edges[MAX_EDGES];
    int edge_cnt = 0;
    char line[256];

    while (fgets(line, sizeof(line), stdin) != NULL) {
        int u, v, w;
        if (sscanf(line, "%d-%d %d", &u, &v, &w) == 3 ||
            sscanf(line, "%d %d %d",   &u, &v, &w) == 3) {
            if (edge_cnt >= MAX_EDGES)
                break;                     /* safety guard */
            edges[edge_cnt].u = u;
            edges[edge_cnt].v = v;
            edges[edge_cnt].w = w;
            ++edge_cnt;
        }
        /* malformed lines are ignored */
    }

    /* ---------- Kruskal's algorithm ---------- */
    for (int i = 0; i < n; ++i)
        parent[i] = i;

    qsort(edges, edge_cnt, sizeof(Edge), cmp_edge);

    Edge mst[MAX_VERTICES - 1];   /* at most n‑1 edges in a spanning tree */
    int mst_cnt = 0;
    int total_weight = 0;

    for (int i = 0; i < edge_cnt && mst_cnt < n - 1; ++i) {
        int a = edges[i].u;
        int b = edges[i].v;
        if (a < 0 || a >= n || b < 0 || b >= n)
            continue;               /* ignore out‑of‑range vertices */
        if (find_set(a) != find_set(b)) {
            union_set(a, b);
            mst[mst_cnt++] = edges[i];
            total_weight += edges[i].w;
        }
    }

    /* ---------- output ---------- */
    if (mst_cnt != n - 1) {
        puts("DISCONNECTED");
        return 0;
    }

    printf("weight=%d edges=", total_weight);
    for (int i = 0; i < mst_cnt; ++i) {
        printf("%d-%d", mst[i].u, mst[i].v);
    }
    putchar('\n');
    return 0;
}
